// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller) public {
        // keep caller wide but not zero-address to be a meaningful EOA
        vm.assume(caller != address(0));

        // call owner() as the fuzzed caller
        bool ok;
        address returned;
        // simulate the call from `caller`
        vm.prank(caller);
        try c.owner() returns (address v) {
            ok = true;
            returned = v;
        } catch {
            ok = false;
            returned = address(0);
        }

        // The reference contract always returns the stored owner (deployer `address(this)` from setUp)
        // So for all callers the call should succeed (ok == true) and the returned value should equal the deployer
        // The mutant that returns msg.sender would make returned == caller for some callers, violating this.
        assertTrue(ok && returned == address(this));
    }
}

