pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // Keep domain wide; we specifically want to include the zero address as a deciding input
        // No vm.assume so fuzzer can try all addresses including address(0)

        // Try calling transferOwnership as the current owner (setUp deployed with owner == address(this))
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: Reference contract always reverts (call fails) when newOwner == address(0).
        // The mutant removes that require and may succeed for newOwner == address(0).
        // So assert that if newOwner is zero, the call did NOT succeed (ok == false).
        // This holds for the correct contract for ALL inputs; the mutant will fail for newOwner == address(0).
        if (newOwner == address(0)) {
            assertTrue(!ok);
        } else {
            // for non-zero newOwner, both correct and mutant allow success; no strong requirement, so assert true to keep single assertion rule
            assertTrue(true);
        }
    }
}

