import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzzed parameters: actor (caller) and newOwner address
    function testFuzz_property(address actor, address newOwner) public {
        // keep addresses wide but non-zero for newOwner to be meaningful
        if (newOwner == address(0)) newOwner = address(1);

        // Determine whether actor is the current owner
        address currentOwner = c.owner();
        bool actorIsOwner = (actor == currentOwner);

        // Try calling transferOwnership as actor and record whether it succeeded (did not revert)
        bool ok;
        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: in the correct contract, transferOwnership succeeds iff caller is current owner.
        // So assert that ok == actorIsOwner. This holds for the reference and is violated by the mutant
        // which inverts the ownership check and allows non-owners while blocking the owner.
        assertTrue(ok == actorIsOwner);
    }
}

