pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzz parameters: caller address and a candidate newOwner address
    function testFuzz_property(address caller, address newOwner) public {
        // Keep wide domain but avoid the zero address for newOwner to keep it meaningful
        // (zero is allowed by contract for transferOwnership? contract disallows zero in transferOwnership)
        // We avoid constraining caller == address(0) because vm.prank cannot set 0; enforce non-zero caller.
        if (caller == address(0)) caller = address(1);
        if (newOwner == address(0)) newOwner = address(1);

        // Determine current owner (should be address(this) as set in constructor)
        address currentOwner = c.owner();
        bool ok;

        // Try calling transferOwnership as `caller` and record whether it reverted/succeeded
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: on the reference implementation, transferOwnership succeeds iff caller == owner()
        // We assert that if caller == currentOwner then the call must succeed; otherwise it must revert.
        // This is a single assertion about c's observed behavior for the given (caller,newOwner).
        if (caller == currentOwner) {
            assertTrue(ok);
        } else {
            assertTrue(!ok);
        }
    }
}

