pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzzed parameters: caller address and candidate newOwner address
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses not zero to be meaningful
        if (caller == address(0) || newOwner == address(0)) return;

        // Record original owner
        address originalOwner = c.owner();

        // We'll attempt transferOwnership from 'caller'
        bool ok;
        // perform call as caller to c.transferOwnership(newOwner)
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert (one boolean):
        // In the reference, transferOwnership succeeds (ok==true) iff caller == originalOwner
        // and when it succeeds the contract owner() becomes newOwner; when it fails owner() remains originalOwner.
        // We assert that one of these two consistent outcomes hold (this is what the reference always guarantees):
        //   - if caller == originalOwner then call must succeed and owner() == newOwner
        //   - if caller != originalOwner then call must revert and owner() == originalOwner
        // This single assertTrue encodes that invariant by checking the matching of ok and owner change.

        bool invariantHolds = (caller == originalOwner && ok && c.owner() == newOwner) ||
                              (caller != originalOwner && !ok && c.owner() == originalOwner);

        assertTrue(invariantHolds);
    }
}

