pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzz: caller and candidate newOwner
    function testFuzz_property(address caller, address newOwner) public {
        // Keep domain wide but avoid zero-address newOwner because reference prevents transferring to zero
        // and to ensure owner change can be meaningfully observed.
        if (newOwner == address(0)) newOwner = address(0xdead);

        // Determine prior owner
        address priorOwner = c.owner();

        bool ok;
        // Perform the transferOwnership call from `caller` and observe whether it succeeded
        // We must prank as the caller to simulate msg.sender
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: if the call succeeded, then the contract's owner() must equal caller
        // This property holds for the correct contract: only the caller who is owner can succeed and then owner()==caller.
        // The mutant inverts the onlyOwner check and will allow some non-owner caller to succeed and set owner to newOwner != caller,
        // violating this assertion for some inputs (fuzzer will find them).
        assertTrue(!ok || c.owner() == caller);
    }
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Attempt by a non-owner to change rewardDistributor must not succeed.
    // Inputs: caller address (as msg.sender) cannot be controlled directly in Solidity here,
    // so we use the external function to be called by an arbitrary address when testing.
    // The test function performs a call that sets rewardDistributor (must be done by the test caller),
    // then reads rewardDistributor and asserts it is unchanged if the caller is not the owner.

    // To express caller identity, the verifier will invoke this function from different senders.
    function run(address newDistributor) external {
        // Read current distributor before attempt
        address before = c.rewardDistributor();

        // Attempt to set distributor as the current caller (this will be msg.sender of this call)
        // This is a state-changing call on c and must be a top-level statement.
        c.setRewardDistributor(newDistributor);

        // Read distributor after attempt
        address after = c.rewardDistributor();

        // If caller is not the owner, then the distributor must remain unchanged.
        // Formally: either caller is the owner (in which case change may be allowed) OR the stored value equals before.
        // We cannot call owner() inside a require that changes state, but owner() is a view so safe to call here.
        address ownerAddr = c.owner();

        assert(msg.sender == ownerAddr || after == before);
    }

    // allow receiving ether (not used but harmless)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address newDistributor) public payable {
        // require the caller is not the owner to capture the distinguishing condition
        require(c.owner() != caller, "caller must not be owner");
        // perform the call as the specified caller by using a call to the contract address
        // We invoke setRewardDistributor via low-level call to control msg.sender.
        (bool success, ) = address(c).call(abi.encodeWithSelector(C.setRewardDistributor.selector, newDistributor));
        bool reverted = !success;
        // The general rule: non-owner attempts must revert
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        bool reverted;
        // make the external call as the provided caller by using low-level call to this test which then forwards
        // We need to invoke c.setRewardDistributor from address `caller`. We cannot change msg.sender directly here,
        // so we require that caller is this contract (the owner) or not. To simulate both, we just call c.setRewardDistributor
        // directly: when this test contract is not the owner, the call must revert on P; when it is the owner, it must not.
        // The constructor of C set its owner to the deployer of C; our test cannot know that, so we encode the rule in terms
        // of whether this test contract is the owner by reading c.owner().
        address owner = c.owner();
        bool amOwner = (owner == address(this));
        // Perform the state-changing call (must be top-level). Use caller parameter only to choose the distributor value.
        // If caller == address(0) was rejected above, now use it as the new distributor value.
        address newDistributor = caller;
        try c.setRewardDistributor(newDistributor) { reverted = false; } catch { reverted = true; }
        // General rule: if this contract is the owner, the call must NOT revert; otherwise it MUST revert.
        assert(amOwner ? reverted == false : reverted == true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // single test function: call setRewardDistributor and assert getter matches argument
    function run(address newDistributor) public {
        // onlyOwner modifier in original requires caller to be owner; the test caller is not owner by default
        // so require that this contract is the owner to allow the call to succeed
        // Check owner via public owner() function
        address owner = c.owner();
        require(owner == address(this), "test contract must be owner");

        // perform the state-changing call
        c.setRewardDistributor(newDistributor);

        // observe public getter and assert it equals the argument
        assert(c.rewardDistributor() == newDistributor);
    }

    // allow receiving ETH if needed by caller setup
    receive() external payable {}
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // single test function: call setRewardDistributor and assert stored value equals input
    function run(address newDistributor) public {
        // onlyOwner restriction: caller must be owner of c; ensure precondition
        // require that msg.sender is owner by using c.owner() equality
        require(c.owner() == msg.sender, "caller not owner");

        // perform the state-changing call
        c.setRewardDistributor(newDistributor);

        // check that the stored value matches the input exactly
        assert(c.rewardDistributor() == newDistributor);
    }

    // allow receiving ETH if needed by other tests
    receive() external payable {}
}
